import type { ExerciseRecord } from './types';

export const CORE_EXERCISE_RECORDS: ExerciseRecord[] = [{"id":"ex-90-90-hamstring","slug":"90-90-hamstring","name":"90/90 Hamstring","description":"Bodyweight exercise for the hamstrings, with calves assisting.","instructions":["Lie on your back, with one leg extended straight out.","With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.","Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.","Repeat for 10-20 repetitions, and then switch to the other leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES"],"equipment":"BODYWEIGHT","tags":["90/90 hamstring"],"media":[{"id":"90-90-hamstring-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/90_90_Hamstring/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"90-90-hamstring-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/90_90_Hamstring/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelrückseite, unterstützt von Waden.","instructions":null}},{"id":"ex-ab-crunch-machine","slug":"ab-crunch-machine","name":"Ab Crunch Machine","description":"Machine exercise for the core.","instructions":["Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.","At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.","After a second pause, slowly return to the starting position as you breathe in.","Repeat the movement for the prescribed amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["ab crunch machine"],"media":[{"id":"ab-crunch-machine-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Crunch_Machine/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"ab-crunch-machine-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Crunch_Machine/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für den Rumpf.","instructions":null}},{"id":"ex-alternate-heel-touchers","slug":"alternate-heel-touchers","name":"Alternate Heel Touchers","description":"Bodyweight exercise for the core.","instructions":["Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.","Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.","Now go back slowly to the starting position as you inhale.","Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.","Continue alternating sides in this manner until all prescribed repetitions are done."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["alternate heel touchers"],"media":[{"id":"alternate-heel-touchers-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Heel_Touchers/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"alternate-heel-touchers-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Heel_Touchers/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-ankle-on-the-knee","slug":"ankle-on-the-knee","name":"Ankle On The Knee","description":"Equipment-free exercise for the glutes.","instructions":["From a lying position, bend your knees and keep your feet on the floor.","Place your ankle of one foot on your opposite knee.","Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"NONE","tags":["ankle on the knee"],"media":[{"id":"ankle-on-the-knee-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ankle_On_The_Knee/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"ankle-on-the-knee-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ankle_On_The_Knee/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Po.","instructions":null}},{"id":"ex-arnold-dumbbell-press","slug":"arnold-dumbbell-press","name":"Arnold Dumbbell Press","description":"Dumbbell exercise for the shoulders, with triceps assisting.","instructions":["Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.","Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.","Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.","After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"DUMBBELL","tags":["arnold dumbbell press"],"media":[{"id":"arnold-dumbbell-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"arnold-dumbbell-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-barbell-bench-press-medium-grip","slug":"barbell-bench-press-medium-grip","name":"Barbell Bench Press - Medium Grip","description":"Barbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.","After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["barbell bench press - medium grip"],"media":[{"id":"barbell-bench-press-medium-grip-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-bench-press-medium-grip-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-barbell-curl","slug":"barbell-curl","name":"Barbell Curl","description":"Barbell exercise for the biceps, with forearms assisting.","instructions":["Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"BARBELL","tags":["barbell curl"],"media":[{"id":"barbell-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-barbell-deadlift","slug":"barbell-deadlift","name":"Barbell Deadlift","description":"Barbell exercise for the back, with calves, forearms, glutes, hamstrings, quadriceps assisting.","instructions":["Stand in front of a loaded barbell.","While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.","While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.","Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.","Perform the amount of repetitions prescribed in the program."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["CALVES","FOREARMS","GLUTES","HAMSTRINGS","QUADRICEPS"],"equipment":"BARBELL","tags":["barbell deadlift"],"media":[{"id":"barbell-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Waden, Unterarme, Po, Oberschenkelrückseite, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-barbell-glute-bridge","slug":"barbell-glute-bridge","name":"Barbell Glute Bridge","description":"Barbell exercise for the glutes, with calves, hamstrings assisting.","instructions":["Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.","Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.","Extend as far as possible, then reverse the motion to return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["CALVES","HAMSTRINGS"],"equipment":"BARBELL","tags":["barbell glute bridge"],"media":[{"id":"barbell-glute-bridge-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-glute-bridge-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Po, unterstützt von Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-barbell-hip-thrust","slug":"barbell-hip-thrust","name":"Barbell Hip Thrust","description":"Barbell exercise for the glutes, with calves, hamstrings assisting.","instructions":["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.","Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.","Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["CALVES","HAMSTRINGS"],"equipment":"BARBELL","tags":["barbell hip thrust"],"media":[{"id":"barbell-hip-thrust-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-hip-thrust-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Po, unterstützt von Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-barbell-incline-bench-press-medium-grip","slug":"barbell-incline-bench-press-medium-grip","name":"Barbell Incline Bench Press - Medium Grip","description":"Barbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on you upper chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["barbell incline bench press - medium grip"],"media":[{"id":"barbell-incline-bench-press-medium-grip-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-incline-bench-press-medium-grip-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-barbell-lunge","slug":"barbell-lunge","name":"Barbell Lunge","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>","Using mainly the heel of your foot, push up and go back to the starting position as you exhale.","Repeat the movement for the recommended amount of repetitions and then perform with the left leg."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["barbell lunge"],"media":[{"id":"barbell-lunge-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Lunge/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-lunge-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Lunge/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-barbell-shoulder-press","slug":"barbell-shoulder-press","name":"Barbell Shoulder Press","description":"Barbell exercise for the shoulders, with chest, triceps assisting.","instructions":["Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).","Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.","Lower the bar down to the shoulders slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST","TRICEPS"],"equipment":"BARBELL","tags":["barbell shoulder press"],"media":[{"id":"barbell-shoulder-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shoulder_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-shoulder-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shoulder_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Brust, Trizeps.","instructions":null}},{"id":"ex-barbell-shrug","slug":"barbell-shrug","name":"Barbell Shrug","description":"Barbell exercise for the back.","instructions":["Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.","Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["barbell shrug"],"media":[{"id":"barbell-shrug-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shrug/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-shrug-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shrug/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken.","instructions":null}},{"id":"ex-barbell-squat","slug":"barbell-squat","name":"Barbell Squat","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["barbell squat"],"media":[{"id":"barbell-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-bench-dips","slug":"bench-dips","name":"Bench Dips","description":"Bodyweight exercise for the triceps, with chest, shoulders assisting.","instructions":["For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.","Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.","Using your triceps to bring your torso up again, lift yourself back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"BODYWEIGHT","tags":["bench dips"],"media":[{"id":"bench-dips-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Dips/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bench-dips-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Dips/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-bent-over-barbell-row","slug":"bent-over-barbell-row","name":"Bent Over Barbell Row","description":"Barbell exercise for the back, with biceps, shoulders assisting.","instructions":["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.","Then inhale and slowly lower the barbell back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"BARBELL","tags":["bent over barbell row"],"media":[{"id":"bent-over-barbell-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bent-over-barbell-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-bent-over-two-dumbbell-row","slug":"bent-over-two-dumbbell-row","name":"Bent Over Two-Dumbbell Row","description":"Dumbbell exercise for the back, with biceps, shoulders assisting.","instructions":["With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"DUMBBELL","tags":["bent over two-dumbbell row"],"media":[{"id":"bent-over-two-dumbbell-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Two-Dumbbell_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bent-over-two-dumbbell-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Two-Dumbbell_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-bird-dog","slug":"bird-dog","name":"Bird Dog","description":"Bodyweight exercise for the core, with shoulders, glutes assisting.","instructions":["The Bird Dog is a core stability exercise that enhances balance, coordination, and spinal alignment. It’s a low-impact movement ideal for strengthening the posterior chain and improving overall functional control.","Begin on all fours with hands under shoulders and knees under hips, keeping your spine neutral.","Extend your right arm forward and left leg backward simultaneously, keeping hips square.","Pause briefly at full extension while engaging your core and glutes.","Return to the starting position and repeat on the opposite side"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["SHOULDERS","GLUTES"],"equipment":"BODYWEIGHT","tags":["bird dog"],"media":[{"id":"bird-dog-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1572/3d14e761-a73d-49da-8804-f3016a7573ff.png","caption":"Bird Dog","attribution":"wger.de · Settebello","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Bird Dog","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Schultern, Po.","instructions":["Der Bird Dog ist eine Übung für die Rumpfstabilität, die Gleichgewicht, Koordination und die Ausrichtung der Wirbelsäule verbessert. Es ist eine gelenkschonende Bewegung, die sich ideal zum Stärken der hinteren Muskelkette und zur Verbesserung der allgemeinen funktionellen Kontrolle eignet.","Beginne im Vierfüßlerstand mit den Händen unter den Schultern und den Knien unter den Hüften und halte deine Wirbelsäule neutral.","Strecke gleichzeitig deinen rechten Arm nach vorn und dein linkes Bein nach hinten und halte die Hüften gerade.","Halte bei voller Streckung kurz inne, während du Rumpf und Gesäßmuskulatur anspannst.","Kehre in die Ausgangsposition zurück und wiederhole die Bewegung auf der anderen Seite"]}},{"id":"ex-bodyweight-squat","slug":"bodyweight-squat","name":"Bodyweight Squat","description":"Bodyweight exercise for the quadriceps, with glutes, hamstrings assisting.","instructions":["Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["bodyweight squat"],"media":[{"id":"bodyweight-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bodyweight-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-butt-lift-bridge","slug":"butt-lift-bridge","name":"Butt Lift (Bridge)","description":"Bodyweight exercise for the glutes, with hamstrings assisting.","instructions":["Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.","Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.","Slowly go back to the starting position as you breathe in."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["butt lift (bridge)"],"media":[{"id":"butt-lift-bridge-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butt_Lift_Bridge/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"butt-lift-bridge-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butt_Lift_Bridge/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelrückseite.","instructions":null}},{"id":"ex-butterfly","slug":"butterfly","name":"Butterfly","description":"Machine exercise for the chest.","instructions":["Sit on the machine with your back flat on the pad.","Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.","Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.","Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["butterfly"],"media":[{"id":"butterfly-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"butterfly-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Brust.","instructions":null}},{"id":"ex-cable-crossover","slug":"cable-crossover","name":"Cable Crossover","description":"Cable exercise for the chest, with shoulders assisting.","instructions":["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.","Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS"],"equipment":"CABLE","tags":["cable crossover"],"media":[{"id":"cable-crossover-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crossover/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-crossover-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crossover/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Brust, unterstützt von Schultern.","instructions":null}},{"id":"ex-cable-crunch","slug":"cable-crunch","name":"Cable Crunch","description":"Cable exercise for the core.","instructions":["Kneel below a high pulley that contains a rope attachment.","Grasp cable rope attachment and lower the rope until your hands are placed next to your face.","Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.","With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.","Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable crunch"],"media":[{"id":"cable-crunch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crunch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-crunch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crunch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rumpf.","instructions":null}},{"id":"ex-cable-rear-delt-fly","slug":"cable-rear-delt-fly","name":"Cable Rear Delt Fly","description":"Cable exercise for the shoulders.","instructions":["Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.","Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.","Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.","Pause at the end of the motion before returning the handles to the start position."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable rear delt fly"],"media":[{"id":"cable-rear-delt-fly-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rear_Delt_Fly/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-rear-delt-fly-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rear_Delt_Fly/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Schultern.","instructions":null}},{"id":"ex-cable-rope-overhead-triceps-extension","slug":"cable-rope-overhead-triceps-extension","name":"Cable Rope Overhead Triceps Extension","description":"Cable exercise for the triceps.","instructions":["Attach a rope to the bottom pulley of the pulley machine.","Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.","Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.","Return to the starting position by flexing your triceps as you breathe out.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable rope overhead triceps extension"],"media":[{"id":"cable-rope-overhead-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-rope-overhead-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Trizeps.","instructions":null}},{"id":"ex-cable-seated-lateral-raise","slug":"cable-seated-lateral-raise","name":"Cable Seated Lateral Raise","description":"Cable exercise for the shoulders, with back assisting.","instructions":["Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.","Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.","Bend forward while keeping your back flat and rest your torso on the thighs.","Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.","While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.","Slowly lower your arms to the starting position as you inhale.","Repeat for the recommended amount of repetitions. Tip: Maintain upper arms perpendicular to torso and a fixed elbow position (10 degree to 30 degree angle) throughout exercise."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"CABLE","tags":["cable seated lateral raise"],"media":[{"id":"cable-seated-lateral-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-seated-lateral-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Schultern, unterstützt von Rücken.","instructions":null}},{"id":"ex-cable-shrugs","slug":"cable-shrugs","name":"Cable Shrugs","description":"Cable exercise for the back.","instructions":["Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.","Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position.","Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shoulders should be moving up and down.","Lower the bar back to the original position.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable shrugs"],"media":[{"id":"cable-shrugs-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Shrugs/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-shrugs-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Shrugs/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken.","instructions":null}},{"id":"ex-cat-stretch","slug":"cat-stretch","name":"Cat Stretch","description":"Equipment-free exercise for the back.","instructions":["Position yourself on the floor on your hands and knees.","Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.","Hold for 15 seconds."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"NONE","tags":["cat stretch"],"media":[{"id":"cat-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cat_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cat-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cat_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken.","instructions":null}},{"id":"ex-chest-and-front-of-shoulder-stretch","slug":"chest-and-front-of-shoulder-stretch","name":"Chest And Front Of Shoulder Stretch","description":"Accessory exercise for the chest, with shoulders assisting.","instructions":["Start off by standing with your legs together, holding a bodybar or a broomstick.","Take a slightly wider than shoulder width grip on the pole and hold it in front of you with your palms facing down.","Carefully lift the pole up and behind your head."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS"],"equipment":"OTHER","tags":["chest and front of shoulder stretch"],"media":[{"id":"chest-and-front-of-shoulder-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_And_Front_Of_Shoulder_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"chest-and-front-of-shoulder-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_And_Front_Of_Shoulder_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Schultern.","instructions":null}},{"id":"ex-childs-pose","slug":"childs-pose","name":"Child's Pose","description":"Equipment-free exercise for the back, with glutes assisting.","instructions":["Get on your hands and knees, walk your hands in front of you.","Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.","Once you settle onto your heels, bring your hands next to your feet and relax. \"breathe\" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["GLUTES"],"equipment":"NONE","tags":["child's pose"],"media":[{"id":"childs-pose-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Childs_Pose/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"childs-pose-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Childs_Pose/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken, unterstützt von Po.","instructions":null}},{"id":"ex-chin-up","slug":"chin-up","name":"Chin-Up","description":"Bodyweight exercise for the back, with biceps, forearms assisting.","instructions":["Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.","As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","FOREARMS"],"equipment":"BODYWEIGHT","tags":["chin-up"],"media":[{"id":"chin-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"chin-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rücken, unterstützt von Bizeps, Unterarme.","instructions":null}},{"id":"ex-close-grip-barbell-bench-press","slug":"close-grip-barbell-bench-press","name":"Close-Grip Barbell Bench Press","description":"Barbell exercise for the triceps, with chest, shoulders assisting.","instructions":["Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"BARBELL","tags":["close-grip barbell bench press"],"media":[{"id":"close-grip-barbell-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Barbell_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"close-grip-barbell-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Barbell_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-close-grip-front-lat-pulldown","slug":"close-grip-front-lat-pulldown","name":"Close-Grip Front Lat Pulldown","description":"Cable exercise for the back, with biceps, shoulders assisting.","instructions":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.","After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","6. Repeat this motion for the prescribed amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"CABLE","tags":["close-grip front lat pulldown"],"media":[{"id":"close-grip-front-lat-pulldown-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Front_Lat_Pulldown/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"close-grip-front-lat-pulldown-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Front_Lat_Pulldown/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-cross-body-crunch","slug":"cross-body-crunch","name":"Cross-Body Crunch","description":"Bodyweight exercise for the core.","instructions":["Lie flat on your back and bend your knees about 60 degrees.","Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position.","Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember that the key is to contract the abs as you perform the movement; not just to move the elbow.","Now go back down to the starting position as you inhale and repeat with the left elbow and the right knee.","Continue alternating in this manner until all prescribed repetitions are done."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["cross-body crunch"],"media":[{"id":"cross-body-crunch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross-Body_Crunch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cross-body-crunch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross-Body_Crunch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-crunches","slug":"crunches","name":"Crunches","description":"Bodyweight exercise for the core.","instructions":["Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.","Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.","While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.","Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don't cheat yourself by using momentum.","After the one second contraction, begin to come down slowly again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["crunches"],"media":[{"id":"crunches-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunches/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"crunches-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunches/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-decline-crunch","slug":"decline-crunch","name":"Decline Crunch","description":"Bodyweight exercise for the core.","instructions":["Secure your legs at the end of the decline bench and lie down.","Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.","While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.","Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don't cheat yourself by using momentum.","After the one second contraction, begin to come down slowly again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["decline crunch"],"media":[{"id":"decline-crunch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Crunch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"decline-crunch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Crunch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-dips-triceps-version","slug":"dips-triceps-version","name":"Dips - Triceps Version","description":"Bodyweight exercise for the triceps, with chest, shoulders assisting.","instructions":["To get into the starting position, hold your body at arm's length with your arms nearly locked above the bars.","Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.","Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.","Repeat the movement for the prescribed amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"BODYWEIGHT","tags":["dips - triceps version"],"media":[{"id":"dips-triceps-version-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dips_-_Triceps_Version/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dips-triceps-version-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dips_-_Triceps_Version/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-dumbbell-bench-press","slug":"dumbbell-bench-press","name":"Dumbbell Bench Press","description":"Dumbbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.","Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.","Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.","Repeat the movement for the prescribed amount of repetitions of your training program."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"DUMBBELL","tags":["dumbbell bench press"],"media":[{"id":"dumbbell-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-dumbbell-flyes","slug":"dumbbell-flyes","name":"Dumbbell Flyes","description":"Dumbbell exercise for the chest.","instructions":["Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.","Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you're pressing them, but stop and hold just before you lock out. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell flyes"],"media":[{"id":"dumbbell-flyes-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Flyes/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-flyes-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Flyes/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Brust.","instructions":null}},{"id":"ex-dumbbell-incline-row","slug":"dumbbell-incline-row","name":"Dumbbell Incline Row","description":"Dumbbell exercise for the back, with biceps, forearms, shoulders assisting.","instructions":["Using a neutral grip, lean into an incline bench.","Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.","Retract the shoulder blades and flex the elbows to row the dumbbells to your side.","Pause at the top of the motion, and then return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","FOREARMS","SHOULDERS"],"equipment":"DUMBBELL","tags":["dumbbell incline row"],"media":[{"id":"dumbbell-incline-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Incline_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-incline-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Incline_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Rücken, unterstützt von Bizeps, Unterarme, Schultern.","instructions":null}},{"id":"ex-dumbbell-lunges","slug":"dumbbell-lunges","name":"Dumbbell Lunges","description":"Dumbbell exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.","Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.","Using mainly the heel of your foot, push up and go back to the starting position as you exhale.","Repeat the movement for the recommended amount of repetitions and then perform with the left leg."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"DUMBBELL","tags":["dumbbell lunges"],"media":[{"id":"dumbbell-lunges-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lunges/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-lunges-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lunges/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-dumbbell-one-arm-triceps-extension","slug":"dumbbell-one-arm-triceps-extension","name":"Dumbbell One-Arm Triceps Extension","description":"Dumbbell exercise for the triceps.","instructions":["Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.","Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface.","Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.","Slowly lower the dumbbell behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.","Return to the starting position by flexing your triceps as you breathe out. Tip: It is imperative that only the forearm moves. The upper arm should remain at all times stationary next to your head.","Repeat for the recommended amount of repetitions and switch arms."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell one-arm triceps extension"],"media":[{"id":"dumbbell-one-arm-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_One-Arm_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-one-arm-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_One-Arm_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps.","instructions":null}},{"id":"ex-dumbbell-shoulder-press","slug":"dumbbell-shoulder-press","name":"Dumbbell Shoulder Press","description":"Dumbbell exercise for the shoulders, with triceps assisting.","instructions":["While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.","Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.","Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.","Now, exhale and push the dumbbells upward until they touch at the top.","Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"DUMBBELL","tags":["dumbbell shoulder press"],"media":[{"id":"dumbbell-shoulder-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-shoulder-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-dumbbell-shrug","slug":"dumbbell-shrug","name":"Dumbbell Shrug","description":"Dumbbell exercise for the back.","instructions":["Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.","Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.","Lower the dumbbells back to the original position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell shrug"],"media":[{"id":"dumbbell-shrug-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shrug/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-shrug-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shrug/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Rücken.","instructions":null}},{"id":"ex-exercise-ball-crunch","slug":"exercise-ball-crunch","name":"Exercise Ball Crunch","description":"Accessory exercise for the core.","instructions":["Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).","Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position.","With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second.","As you inhale, go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["exercise ball crunch"],"media":[{"id":"exercise-ball-crunch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Exercise_Ball_Crunch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"exercise-ball-crunch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Exercise_Ball_Crunch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf.","instructions":null}},{"id":"ex-ez-bar-curl","slug":"ez-bar-curl","name":"EZ-Bar Curl","description":"EZ-bar exercise for the biceps.","instructions":["Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.","Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.","Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.","Then inhale and slowly lower the bar back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"EZ_BAR","tags":["ez-bar curl"],"media":[{"id":"ez-bar-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"ez-bar-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (SZ-Stange) für den Bizeps.","instructions":null}},{"id":"ex-face-pull","slug":"face-pull","name":"Face Pull","description":"Cable exercise for the shoulders, with back assisting.","instructions":["Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"CABLE","tags":["face pull"],"media":[{"id":"face-pull-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"face-pull-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Schultern, unterstützt von Rücken.","instructions":null}},{"id":"ex-flat-bench-lying-leg-raise","slug":"flat-bench-lying-leg-raise","name":"Flat Bench Lying Leg Raise","description":"Bodyweight exercise for the core.","instructions":["Lie with your back flat on a bench and your legs extended in front of you off the end.","Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.","As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.","Now, as you inhale, slowly lower your legs back down to the starting position."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["flat bench lying leg raise"],"media":[{"id":"flat-bench-lying-leg-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Lying_Leg_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"flat-bench-lying-leg-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Lying_Leg_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-flutter-kicks","slug":"flutter-kicks","name":"Flutter Kicks","description":"Bodyweight exercise for the glutes, with hamstrings assisting.","instructions":["On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.","Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.","Start the movement by lifting the left leg higher than the right leg.","Then lower the left leg as you lift the right leg.","Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["flutter kicks"],"media":[{"id":"flutter-kicks-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flutter_Kicks/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"flutter-kicks-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flutter_Kicks/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelrückseite.","instructions":null}},{"id":"ex-front-dumbbell-raise","slug":"front-dumbbell-raise","name":"Front Dumbbell Raise","description":"Dumbbell exercise for the shoulders.","instructions":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.","Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.","Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["front dumbbell raise"],"media":[{"id":"front-dumbbell-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Dumbbell_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"front-dumbbell-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Dumbbell_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-front-plate-raise","slug":"front-plate-raise","name":"Front Plate Raise","description":"Accessory exercise for the shoulders.","instructions":["While standing straight, hold a barbell plate in both hands at the 3 and 9 o'clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position.","Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. Tip: make sure that you do not swing the weight or bend at the elbows. Your torso should remain stationary throughout the movement as well.","As you inhale, slowly lower the plate back down to the starting position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["front plate raise"],"media":[{"id":"front-plate-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Plate_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"front-plate-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Plate_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Schultern.","instructions":null}},{"id":"ex-goblet-squat","slug":"goblet-squat","name":"Goblet Squat","description":"Kettlebell exercise for the quadriceps, with calves, glutes, hamstrings, shoulders assisting.","instructions":["Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.","Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.","At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","SHOULDERS"],"equipment":"KETTLEBELL","tags":["goblet squat"],"media":[{"id":"goblet-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Goblet_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"goblet-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Goblet_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Schultern.","instructions":null}},{"id":"ex-groin-and-back-stretch","slug":"groin-and-back-stretch","name":"Groin and Back Stretch","description":"Equipment-free exercise for the quadriceps.","instructions":["Sit on the floor with your knees bent and feet together.","Interlock your fingers behind your head. This will be your starting position.","Curl downwards, bringing your elbows to the inside of your thighs. After a brief pause, return to the starting position with your head up and your back straight. Repeat for 10-20 repetitions."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"NONE","tags":["groin and back stretch"],"media":[{"id":"groin-and-back-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Groin_and_Back_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"groin-and-back-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Groin_and_Back_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-hammer-curls","slug":"hammer-curls","name":"Hammer Curls","description":"Dumbbell exercise for the biceps.","instructions":["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. This will be your starting position.","Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.","After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["hammer curls"],"media":[{"id":"hammer-curls-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Curls/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hammer-curls-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Curls/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps.","instructions":null}},{"id":"ex-hanging-leg-raise","slug":"hanging-leg-raise","name":"Hanging Leg Raise","description":"Bodyweight exercise for the core.","instructions":["Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.","Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.","Go back slowly to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["hanging leg raise"],"media":[{"id":"hanging-leg-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hanging-leg-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-high-cable-curls","slug":"high-cable-curls","name":"High Cable Curls","description":"Cable exercise for the biceps.","instructions":["Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position.","Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps.","Slowly bring back the arms to the starting position.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["high cable curls"],"media":[{"id":"high-cable-curls-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/High_Cable_Curls/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"high-cable-curls-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/High_Cable_Curls/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Bizeps.","instructions":null}},{"id":"ex-hug-knees-to-chest","slug":"hug-knees-to-chest","name":"Hug Knees To Chest","description":"Equipment-free exercise for the back, with glutes assisting.","instructions":["Lie down on your back and pull both knees up to your chest.","Hold your arms under the knees, not over (that would put to much pressure on your knee joints).","Slowly pull the knees toward your shoulders. This also stretches your buttocks muscles."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["GLUTES"],"equipment":"NONE","tags":["hug knees to chest"],"media":[{"id":"hug-knees-to-chest-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hug_Knees_To_Chest/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hug-knees-to-chest-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hug_Knees_To_Chest/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken, unterstützt von Po.","instructions":null}},{"id":"ex-hyperextensions-back-extensions","slug":"hyperextensions-back-extensions","name":"Hyperextensions (Back Extensions)","description":"Accessory exercise for the back, with glutes, hamstrings assisting.","instructions":["Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.","Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.","With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.","Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.","Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["GLUTES","HAMSTRINGS"],"equipment":"OTHER","tags":["hyperextensions (back extensions)"],"media":[{"id":"hyperextensions-back-extensions-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hyperextensions_Back_Extensions/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hyperextensions-back-extensions-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hyperextensions_Back_Extensions/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-incline-dumbbell-curl","slug":"incline-dumbbell-curl","name":"Incline Dumbbell Curl","description":"Dumbbell exercise for the biceps.","instructions":["Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["incline dumbbell curl"],"media":[{"id":"incline-dumbbell-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-dumbbell-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps.","instructions":null}},{"id":"ex-incline-dumbbell-flyes","slug":"incline-dumbbell-flyes","name":"Incline Dumbbell Flyes","description":"Dumbbell exercise for the chest, with shoulders assisting.","instructions":["Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.","Extend your arms above you with a slight bend at the elbows.","Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.","As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.","As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS"],"equipment":"DUMBBELL","tags":["incline dumbbell flyes"],"media":[{"id":"incline-dumbbell-flyes-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-dumbbell-flyes-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Brust, unterstützt von Schultern.","instructions":null}},{"id":"ex-incline-dumbbell-press","slug":"incline-dumbbell-press","name":"Incline Dumbbell Press","description":"Dumbbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.","Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.","Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.","Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"DUMBBELL","tags":["incline dumbbell press"],"media":[{"id":"incline-dumbbell-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-dumbbell-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-jackknife-sit-up","slug":"jackknife-sit-up","name":"Jackknife Sit-Up","description":"Bodyweight exercise for the core.","instructions":["Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also. This will be your starting position.","As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. Tip: The legs should be extended and lifted at approximately a 35-45 degree angle from the floor and the arms should be extended and parallel to your legs. The upper torso should be off the floor.","While inhaling, lower your arms and legs back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["jackknife sit-up"],"media":[{"id":"jackknife-sit-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jackknife_Sit-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"jackknife-sit-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jackknife_Sit-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-knee-hip-raise-on-parallel-bars","slug":"knee-hip-raise-on-parallel-bars","name":"Knee/Hip Raise On Parallel Bars","description":"Accessory exercise for the core.","instructions":["Position your body on the vertical leg raise bench so that your forearms are resting on the pads next to the torso and holding on to the handles. Your arms will be bent at a 90 degree angle.","The torso should be straight with the lower back pressed against the pad of the machine and the legs extended pointing towards the floor. This will be your starting position.","Now as you breathe out, lift your legs up as you keep them extended. Continue this movement until your legs are roughly parallel to the floor and then hold the contraction for a second. Tip: Do not use any momentum or swinging as you perform this exercise.","Slowly go back to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["knee/hip raise on parallel bars"],"media":[{"id":"knee-hip-raise-on-parallel-bars-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Knee_Hip_Raise_On_Parallel_Bars/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"knee-hip-raise-on-parallel-bars-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Knee_Hip_Raise_On_Parallel_Bars/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf.","instructions":null}},{"id":"ex-kneeling-forearm-stretch","slug":"kneeling-forearm-stretch","name":"Kneeling Forearm Stretch","description":"Equipment-free exercise for the forearms.","instructions":["Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees.","Slowly lean back keeping your palms flat on the floor until you feel a stretch in your wrists and forearms. Hold for 20-30 seconds."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"NONE","tags":["kneeling forearm stretch"],"media":[{"id":"kneeling-forearm-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Forearm_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kneeling-forearm-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Forearm_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Unterarme.","instructions":null}},{"id":"ex-kneeling-hip-flexor","slug":"kneeling-hip-flexor","name":"Kneeling Hip Flexor","description":"Equipment-free exercise for the quadriceps.","instructions":["Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor.","Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"NONE","tags":["kneeling hip flexor"],"media":[{"id":"kneeling-hip-flexor-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Hip_Flexor/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kneeling-hip-flexor-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Hip_Flexor/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-leg-extensions","slug":"leg-extensions","name":"Leg Extensions","description":"Machine exercise for the quadriceps.","instructions":["For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.","Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.","Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.","Repeat for the recommended amount of times."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["leg extensions"],"media":[{"id":"leg-extensions-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"leg-extensions-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-leg-press","slug":"leg-press","name":"Leg Press","description":"Machine exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.","As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.","Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.","Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"MACHINE","tags":["leg press"],"media":[{"id":"leg-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"leg-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-leg-pull-in","slug":"leg-pull-in","name":"Leg Pull-In","description":"Bodyweight exercise for the core.","instructions":["Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.","Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor.","Return to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["leg pull-in"],"media":[{"id":"leg-pull-in-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Pull-In/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"leg-pull-in-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Pull-In/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-leg-up-hamstring-stretch","slug":"leg-up-hamstring-stretch","name":"Leg-Up Hamstring Stretch","description":"Equipment-free exercise for the hamstrings.","instructions":["Lie flat on your back, bend one knee, and put that foot flat on the floor to stabilize your spine.","Extend the other leg in the air. If you're tight, you wont be able to straighten it. That's okay. Extend the knee so that the sole of the lifted foot faces the ceiling (or as close as you can get it).","Slowly straighten the legs as much as possible and then pull the leg toward your nose. Switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"NONE","tags":["leg-up hamstring stretch"],"media":[{"id":"leg-up-hamstring-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg-Up_Hamstring_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"leg-up-hamstring-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg-Up_Hamstring_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelrückseite.","instructions":null}},{"id":"ex-leverage-chest-press","slug":"leverage-chest-press","name":"Leverage Chest Press","description":"Machine exercise for the chest, with shoulders, triceps assisting.","instructions":["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.","Your chest and head should be up and your shoulder blades retracted. This will be your starting position.","Press the handles forward by extending through the elbow.","After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"MACHINE","tags":["leverage chest press"],"media":[{"id":"leverage-chest-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Chest_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"leverage-chest-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Chest_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-leverage-high-row","slug":"leverage-high-row","name":"Leverage High Row","description":"Machine exercise for the back.","instructions":["Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.","Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handles to the starting position.","For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["leverage high row"],"media":[{"id":"leverage-high-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_High_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"leverage-high-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_High_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für den Rücken.","instructions":null}},{"id":"ex-leverage-incline-chest-press","slug":"leverage-incline-chest-press","name":"Leverage Incline Chest Press","description":"Machine exercise for the chest, with shoulders, triceps assisting.","instructions":["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.","Press the handles forward by extending through the elbow.","After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"MACHINE","tags":["leverage incline chest press"],"media":[{"id":"leverage-incline-chest-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Incline_Chest_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"leverage-incline-chest-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Incline_Chest_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-lying-dumbbell-tricep-extension","slug":"lying-dumbbell-tricep-extension","name":"Lying Dumbbell Tricep Extension","description":"Dumbbell exercise for the triceps, with chest, shoulders assisting.","instructions":["Lie on a flat bench while holding two dumbbells directly in front of you. Your arms should be fully extended at a 90-degree angle from your torso and the floor. The palms should be facing in and the elbows should be tucked in. This is the starting position.","As you breathe in and you keep the upper arms stationary with the elbows in, slowly lower the weight until the dumbbells are near your ears.","At that point, while keeping the elbows in and the upper arms stationary, use the triceps to bring the weight back up to the starting position as you breathe out.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"DUMBBELL","tags":["lying dumbbell tricep extension"],"media":[{"id":"lying-dumbbell-tricep-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Dumbbell_Tricep_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-dumbbell-tricep-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Dumbbell_Tricep_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-lying-leg-curls","slug":"lying-leg-curls","name":"Lying Leg Curls","description":"Machine exercise for the hamstrings.","instructions":["Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.","Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.","As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.","As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["lying leg curls"],"media":[{"id":"lying-leg-curls-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Leg_Curls/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-leg-curls-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Leg_Curls/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelrückseite.","instructions":null}},{"id":"ex-machine-lateral-raise","slug":"machine-lateral-raise","name":"Machine Lateral Raise","description":"Machine exercise for the shoulders.","instructions":["The machine lateral raise is an isolation exercise that targets the medial (side) deltoid muscle to build wider, more defined shoulders. The machine's fixed path of motion provides greater stability than dumbbells, making it ideal for beginners or those who want to focus solely on muscle activation."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["machine lateral raise","seitheben an der maschine"],"media":[{"id":"machine-lateral-raise-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1654/aa724a58-b3b5-4522-b278-1155416236a5.jpg","caption":"Machine Lateral Raise","attribution":"wger.de · roneydya","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Seitheben an der Maschine","description":"Übung (Maschine) für die Schultern.","instructions":["Das Seitheben an der Maschine ist eine Isolationsübung, die den mittleren (seitlichen) Anteil des Deltamuskels trainiert, um breitere und definiertere Schultern aufzubauen. Die feste Bewegungsbahn der Maschine bietet mehr Stabilität als Kurzhanteln und macht sie ideal für Einsteiger oder alle, die sich ganz auf die Muskelaktivierung konzentrieren möchten."]}},{"id":"ex-machine-preacher-curls","slug":"machine-preacher-curls","name":"Machine Preacher Curls","description":"Machine exercise for the biceps.","instructions":["Sit down on the Preacher Curl Machine and select the weight.","Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position.","Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. The upper arms should remain stationary and on the pad at all times.","Lower the handles slowly back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["machine preacher curls"],"media":[{"id":"machine-preacher-curls-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Preacher_Curls/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"machine-preacher-curls-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Preacher_Curls/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für den Bizeps.","instructions":null}},{"id":"ex-machine-shoulder-military-press","slug":"machine-shoulder-military-press","name":"Machine Shoulder (Military) Press","description":"Machine exercise for the shoulders, with triceps assisting.","instructions":["Sit down on the Shoulder Press Machine and select the weight.","Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.","Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.","Lower the handles slowly back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"MACHINE","tags":["machine shoulder (military) press"],"media":[{"id":"machine-shoulder-military-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Shoulder_Military_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"machine-shoulder-military-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Shoulder_Military_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-one-arm-dumbbell-row","slug":"one-arm-dumbbell-row","name":"One-Arm Dumbbell Row","description":"Dumbbell exercise for the back, with biceps, shoulders assisting.","instructions":["Choose a flat bench and place a dumbbell on each side of it.","Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.","Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.","Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.","Lower the resistance straight down to the starting position. Breathe in as you perform this step.","Repeat the movement for the specified amount of repetitions.","Switch sides and repeat again with the other arm."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"DUMBBELL","tags":["one-arm dumbbell row"],"media":[{"id":"one-arm-dumbbell-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-dumbbell-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-one-handed-hang","slug":"one-handed-hang","name":"One Handed Hang","description":"Accessory exercise for the back, with biceps assisting.","instructions":["Grab onto a chinup bar with one hand, using a pronated grip. Keep your feet on the floor or a step. Allow the majority of your weight to hang from that hand, while keeping your feet on the ground. Hold for 10-20 seconds and switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"OTHER","tags":["one handed hang"],"media":[{"id":"one-handed-hang-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Handed_Hang/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-handed-hang-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Handed_Hang/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-overhead-triceps","slug":"overhead-triceps","name":"Overhead Triceps","description":"Bodyweight exercise for the triceps, with back assisting.","instructions":["Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your elbow and wrist. This will be your starting position.","Attempt to extend the arm straight into the air as your partner prevents you from doing actually doing so.","After 10-20 seconds, relax the arm and allow your partner to further stretch the tricep by applying gentle pressure to the wrist. Hold for 10-20 seconds, and then switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["BACK"],"equipment":"BODYWEIGHT","tags":["overhead triceps"],"media":[{"id":"overhead-triceps-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Triceps/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"overhead-triceps-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Triceps/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Trizeps, unterstützt von Rücken.","instructions":null}},{"id":"ex-palms-up-barbell-wrist-curl-over-a-bench","slug":"palms-up-barbell-wrist-curl-over-a-bench","name":"Palms-Up Barbell Wrist Curl Over A Bench","description":"Barbell exercise for the forearms.","instructions":["Start out by placing a barbell on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["palms-up barbell wrist curl over a bench"],"media":[{"id":"palms-up-barbell-wrist-curl-over-a-bench-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"palms-up-barbell-wrist-curl-over-a-bench-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Unterarme.","instructions":null}},{"id":"ex-preacher-curl","slug":"preacher-curl","name":"Preacher Curl","description":"Barbell exercise for the biceps.","instructions":["To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.","With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.","As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["preacher curl"],"media":[{"id":"preacher-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"preacher-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Bizeps.","instructions":null}},{"id":"ex-pullups","slug":"pullups","name":"Pullups","description":"Bodyweight exercise for the back, with biceps assisting.","instructions":["Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"BODYWEIGHT","tags":["pullups"],"media":[{"id":"pullups-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"pullups-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-pushups","slug":"pushups","name":"Pushups","description":"Bodyweight exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.","Next, lower yourself downward until your chest almost touches the floor as you inhale.","Now breathe out and press your upper body back up to the starting position while squeezing your chest.","After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["pushups"],"media":[{"id":"pushups-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pushups/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"pushups-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pushups/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-reverse-crunch","slug":"reverse-crunch","name":"Reverse Crunch","description":"Bodyweight exercise for the core.","instructions":["Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.","Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.","While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.","Hold the contraction for a second and move your legs back to the starting position while exhaling.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["reverse crunch"],"media":[{"id":"reverse-crunch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Crunch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-crunch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Crunch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-reverse-grip-triceps-pushdown","slug":"reverse-grip-triceps-pushdown","name":"Reverse Grip Triceps Pushdown","description":"Cable exercise for the triceps.","instructions":["Start by setting a bar attachment (straight or e-z) on a high pulley machine.","Facing the bar attachment, grab it with the palms facing up (supinated grip) at shoulder width. Lower the bar by using your lats until your arms are fully extended by your sides. Tip: Elbows should be in by your sides and your feet should be shoulder width apart from each other. This is the starting position.","Slowly elevate the bar attachment up as you inhale so it is aligned with your chest. Only the forearms should move and the elbows/upper arms should be stationary by your side at all times.","Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["reverse grip triceps pushdown"],"media":[{"id":"reverse-grip-triceps-pushdown-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Grip_Triceps_Pushdown/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-grip-triceps-pushdown-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Grip_Triceps_Pushdown/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Trizeps.","instructions":null}},{"id":"ex-reverse-machine-flyes","slug":"reverse-machine-flyes","name":"Reverse Machine Flyes","description":"Machine exercise for the shoulders.","instructions":["Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.","In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.","Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.","Pause at the rear of the movement, and slowly return the weight to the starting position."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["reverse machine flyes"],"media":[{"id":"reverse-machine-flyes-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Machine_Flyes/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-machine-flyes-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Machine_Flyes/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Schultern.","instructions":null}},{"id":"ex-romanian-deadlift","slug":"romanian-deadlift","name":"Romanian Deadlift","description":"Barbell exercise for the hamstrings, with calves, glutes, back assisting.","instructions":["Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.","Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.","Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.","Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES","BACK"],"equipment":"BARBELL","tags":["romanian deadlift"],"media":[{"id":"romanian-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"romanian-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Waden, Po, Rücken.","instructions":null}},{"id":"ex-rowing-stationary","slug":"rowing-stationary","name":"Rowing, Stationary","description":"Machine exercise for the quadriceps, with biceps, calves, glutes, hamstrings, back assisting.","instructions":["To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.","There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.","The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["BICEPS","CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"MACHINE","tags":["rowing, stationary"],"media":[{"id":"rowing-stationary-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"rowing-stationary-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelvorderseite, unterstützt von Bizeps, Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-seated-bent-over-rear-delt-raise","slug":"seated-bent-over-rear-delt-raise","name":"Seated Bent-Over Rear Delt Raise","description":"Dumbbell exercise for the shoulders.","instructions":["Place a couple of dumbbells looking forward in front of a flat bench.","Sit on the end of the bench with your legs together and the dumbbells behind your calves.","Bend at the waist while keeping the back straight in order to pick up the dumbbells. The palms of your hands should be facing each other as you pick them. This will be your starting position.","Keeping your torso forward and stationary, and the arms slightly bent at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. (Note: avoid swinging the torso or bringing the arms back as opposed to the side.)","After a one second contraction at the top, slowly lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["seated bent-over rear delt raise"],"media":[{"id":"seated-bent-over-rear-delt-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Rear_Delt_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-bent-over-rear-delt-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Rear_Delt_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-seated-cable-rows","slug":"seated-cable-rows","name":"Seated Cable Rows","description":"Cable exercise for the back, with biceps, shoulders assisting.","instructions":["For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the V-bar handles.","With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"CABLE","tags":["seated cable rows"],"media":[{"id":"seated-cable-rows-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-cable-rows-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-seated-calf-raise","slug":"seated-calf-raise","name":"Seated Calf Raise","description":"Machine exercise for the calves.","instructions":["Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.","Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.","Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.","Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.","Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["seated calf raise"],"media":[{"id":"seated-calf-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-calf-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Waden.","instructions":null}},{"id":"ex-seated-dumbbell-curl","slug":"seated-dumbbell-curl","name":"Seated Dumbbell Curl","description":"Dumbbell exercise for the biceps.","instructions":["Sit on a flat bench with a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","Rotate the palms of the hands so that they are facing your torso. This will be your starting position.","While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement. Make sure that you contract the biceps as you breathe out and make sure that only the forearms move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in and as you rotate the wrists back to a neutral grip.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["seated dumbbell curl"],"media":[{"id":"seated-dumbbell-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-dumbbell-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps.","instructions":null}},{"id":"ex-seated-floor-hamstring-stretch","slug":"seated-floor-hamstring-stretch","name":"Seated Floor Hamstring Stretch","description":"Equipment-free exercise for the hamstrings, with calves assisting.","instructions":["Sit on a mat with your right leg extended in front of you and your left leg bent with your foot against your right inner thigh.","Lean forward from your hips and reach for your ankle until you feel a stretch in your hamstring. Hold for 15 seconds, then repeat for your other side."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES"],"equipment":"NONE","tags":["seated floor hamstring stretch"],"media":[{"id":"seated-floor-hamstring-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Floor_Hamstring_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-floor-hamstring-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Floor_Hamstring_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelrückseite, unterstützt von Waden.","instructions":null}},{"id":"ex-seated-leg-curl","slug":"seated-leg-curl","name":"Seated Leg Curl","description":"Machine exercise for the hamstrings.","instructions":["Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.","Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.","As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["seated leg curl"],"media":[{"id":"seated-leg-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Leg_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-leg-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Leg_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelrückseite.","instructions":null}},{"id":"ex-seated-one-arm-cable-pulley-rows","slug":"seated-one-arm-cable-pulley-rows","name":"Seated One-arm Cable Pulley Rows","description":"Cable exercise for the back, with biceps assisting.","instructions":["To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip.","With your arm extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lat as you hold the bar in front of you. The right arm can be kept by the waist. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it as you rotate the wrist, so that by the time your hand is by your abdominals it is in a neutral position (palms facing the torso). Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard.","Hold that contraction for a second and slowly go back to the original position while breathing in. Tip: Remember to rotate the wrist as you go back to the starting position so that the palms are facing down again.","Repeat for the recommended amount of repetitions and then perform the same movement with the right hand."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"CABLE","tags":["seated one-arm cable pulley rows"],"media":[{"id":"seated-one-arm-cable-pulley-rows-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_One-arm_Cable_Pulley_Rows/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-one-arm-cable-pulley-rows-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_One-arm_Cable_Pulley_Rows/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-seated-triceps-press","slug":"seated-triceps-press","name":"Seated Triceps Press","description":"Dumbbell exercise for the triceps.","instructions":["Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm's length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position.","Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["seated triceps press"],"media":[{"id":"seated-triceps-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Triceps_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-triceps-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Triceps_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps.","instructions":null}},{"id":"ex-shoulder-stretch","slug":"shoulder-stretch","name":"Shoulder Stretch","description":"Equipment-free exercise for the shoulders.","instructions":["Reach your left arm across your body and hold it straight."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"NONE","tags":["shoulder stretch"],"media":[{"id":"shoulder-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shoulder_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"shoulder-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shoulder_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Schultern.","instructions":null}},{"id":"ex-side-bridge","slug":"side-bridge","name":"Side Bridge","description":"Bodyweight exercise for the core, with shoulders assisting.","instructions":[],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["SHOULDERS"],"equipment":"BODYWEIGHT","tags":["side bridge"],"media":[{"id":"side-bridge-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Bridge/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"side-bridge-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Bridge/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Schultern.","instructions":null}},{"id":"ex-side-jackknife","slug":"side-jackknife","name":"Side Jackknife","description":"Bodyweight exercise for the core.","instructions":[],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["side jackknife"],"media":[{"id":"side-jackknife-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Jackknife/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"side-jackknife-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Jackknife/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-side-lateral-raise","slug":"side-lateral-raise","name":"Side Lateral Raise","description":"Dumbbell exercise for the shoulders.","instructions":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.","While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbells back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["side lateral raise"],"media":[{"id":"side-lateral-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"side-lateral-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-side-neck-stretch","slug":"side-neck-stretch","name":"Side Neck Stretch","description":"Equipment-free exercise for the shoulders.","instructions":["Start with your shoulders relaxed, gently tilt your head towards your shoulder.","Assist stretch with a gentle pull on the side of the head."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"NONE","tags":["side neck stretch"],"media":[{"id":"side-neck-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Neck_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"side-neck-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Neck_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Schultern.","instructions":null}},{"id":"ex-sit-squats","slug":"sit-squats","name":"Sit Squats","description":"Equipment-free exercise for the quadriceps, with glutes, hamstrings assisting.","instructions":["Stand with your feet shoulder width apart. This will be your starting position.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue until you have squatted a portion of the way down, but are above parallel, and quickly reverse the motion until you return to the starting position. Repeat for 5-10 repetitions."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","HAMSTRINGS"],"equipment":"NONE","tags":["sit squats"],"media":[{"id":"sit-squats-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sit_Squats/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"sit-squats-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sit_Squats/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite, unterstützt von Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-smith-machine-squat","slug":"smith-machine-squat","name":"Smith Machine Squat","description":"Smith machine exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"SMITH_MACHINE","tags":["smith machine squat"],"media":[{"id":"smith-machine-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Multipresse) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-spinal-stretch","slug":"spinal-stretch","name":"Spinal Stretch","description":"Equipment-free exercise for the back, with shoulders assisting.","instructions":["Sit in a chair so your back is straight and your feet planted on the floor.","Interlace your fingers behind your head, elbows out and your chin down.","Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee.","Return to upright position and then repeat for your other side."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["SHOULDERS"],"equipment":"NONE","tags":["spinal stretch"],"media":[{"id":"spinal-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spinal_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"spinal-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spinal_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken, unterstützt von Schultern.","instructions":null}},{"id":"ex-split-squat-with-dumbbells","slug":"split-squat-with-dumbbells","name":"Split Squat with Dumbbells","description":"Dumbbell exercise for the quadriceps, with glutes, hamstrings assisting.","instructions":["Position yourself into a staggered stance with the rear foot elevated and front foot forward.","Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.","Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.","At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","HAMSTRINGS"],"equipment":"DUMBBELL","tags":["split squat with dumbbells"],"media":[{"id":"split-squat-with-dumbbells-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Squat_with_Dumbbells/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"split-squat-with-dumbbells-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Squat_with_Dumbbells/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Oberschenkelvorderseite, unterstützt von Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-standing-biceps-cable-curl","slug":"standing-biceps-cable-curl","name":"Standing Biceps Cable Curl","description":"Cable exercise for the biceps.","instructions":["Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the curl bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["standing biceps cable curl"],"media":[{"id":"standing-biceps-cable-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Cable_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-biceps-cable-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Cable_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Bizeps.","instructions":null}},{"id":"ex-standing-cable-wood-chop","slug":"standing-cable-wood-chop","name":"Standing Cable Wood Chop","description":"Cable exercise for the core, with shoulders assisting.","instructions":["Connect a standard handle to a tower, and move the cable to the highest pulley position.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.","With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.","In one motion, pull the handle down and across your body to your front knee while rotating your torso.","Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.","Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["SHOULDERS"],"equipment":"CABLE","tags":["standing cable wood chop"],"media":[{"id":"standing-cable-wood-chop-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Cable_Wood_Chop/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-cable-wood-chop-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Cable_Wood_Chop/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rumpf, unterstützt von Schultern.","instructions":null}},{"id":"ex-standing-calf-raises","slug":"standing-calf-raises","name":"Standing Calf Raises","description":"Machine exercise for the calves.","instructions":["Adjust the padded lever of the calf raise machine to fit your height.","Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["standing calf raises"],"media":[{"id":"standing-calf-raises-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Calf_Raises/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-calf-raises-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Calf_Raises/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Waden.","instructions":null}},{"id":"ex-standing-dumbbell-press","slug":"standing-dumbbell-press","name":"Standing Dumbbell Press","description":"Dumbbell exercise for the shoulders, with triceps assisting.","instructions":["Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position.","Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head.","Pause, and slowly return the weight to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"DUMBBELL","tags":["standing dumbbell press"],"media":[{"id":"standing-dumbbell-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-dumbbell-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-standing-elevated-quad-stretch","slug":"standing-elevated-quad-stretch","name":"Standing Elevated Quad Stretch","description":"Accessory exercise for the quadriceps.","instructions":["Start by standing with your back about two to three feet away from a bench or step.","Lift one leg behind you and rest your foot on the step,either on your instep or the ball of your foot, whichever you find most comfortable.","Keep your supporting knee slightly bent and avoid letting that knee extend out beyond your toes. Switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["standing elevated quad stretch"],"media":[{"id":"standing-elevated-quad-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Elevated_Quad_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-elevated-quad-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Elevated_Quad_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-standing-gastrocnemius-calf-stretch","slug":"standing-gastrocnemius-calf-stretch","name":"Standing Gastrocnemius Calf Stretch","description":"Equipment-free exercise for the calves, with hamstrings assisting.","instructions":["Place your right heel on a step with your knee extended and lean forward to grab your right toe with your right hand. Your left knee should be slightly bent and your back should be straight.","Support your weight on your left leg and place your left hand on your left thigh.","Pull your right toes toward your knee until you feel a stretch in your calf."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":["HAMSTRINGS"],"equipment":"NONE","tags":["standing gastrocnemius calf stretch"],"media":[{"id":"standing-gastrocnemius-calf-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Gastrocnemius_Calf_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-gastrocnemius-calf-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Gastrocnemius_Calf_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Waden, unterstützt von Oberschenkelrückseite.","instructions":null}},{"id":"ex-standing-hip-flexors","slug":"standing-hip-flexors","name":"Standing Hip Flexors","description":"Equipment-free exercise for the quadriceps.","instructions":["Stand up straight with the spine vertical, the left foot slightly in front of the right.","Bend both knees and lift the back heel off the floor as you press the right hip forward. You can't get a thorough, deep stretch in this position, however, because it's hard to relax the hip flexor and stand on it at the same time. Switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"NONE","tags":["standing hip flexors"],"media":[{"id":"standing-hip-flexors-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Hip_Flexors/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-hip-flexors-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Hip_Flexors/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-standing-leg-curl","slug":"standing-leg-curl","name":"Standing Leg Curl","description":"Machine exercise for the hamstrings.","instructions":["Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.","Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.","As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.","As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.","Perform the same exercise now for the left leg."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["standing leg curl"],"media":[{"id":"standing-leg-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Leg_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-leg-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Leg_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelrückseite.","instructions":null}},{"id":"ex-straight-arm-pulldown","slug":"straight-arm-pulldown","name":"Straight-Arm Pulldown","description":"Cable exercise for the back.","instructions":["You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.","Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.","While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.","While keeping the arms straight, go back to the starting position while breathing in.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["straight-arm pulldown"],"media":[{"id":"straight-arm-pulldown-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Straight-Arm_Pulldown/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"straight-arm-pulldown-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Straight-Arm_Pulldown/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken.","instructions":null}},{"id":"ex-thigh-abductor","slug":"thigh-abductor","name":"Thigh Abductor","description":"Machine exercise for the glutes.","instructions":["To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.","Slowly press against the machine with your legs to move them away from each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["thigh abductor"],"media":[{"id":"thigh-abductor-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Thigh_Abductor/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"thigh-abductor-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Thigh_Abductor/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für den Po.","instructions":null}},{"id":"ex-tricep-dumbbell-kickback","slug":"tricep-dumbbell-kickback","name":"Tricep Dumbbell Kickback","description":"Dumbbell exercise for the triceps.","instructions":["Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.","Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.","After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.","Repeat the movement for the prescribed amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["tricep dumbbell kickback"],"media":[{"id":"tricep-dumbbell-kickback-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Dumbbell_Kickback/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"tricep-dumbbell-kickback-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Dumbbell_Kickback/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps.","instructions":null}},{"id":"ex-triceps-pushdown-rope-attachment","slug":"triceps-pushdown-rope-attachment","name":"Triceps Pushdown - Rope Attachment","description":"Cable exercise for the triceps.","instructions":["Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).","Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.","Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.","After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["triceps pushdown - rope attachment"],"media":[{"id":"triceps-pushdown-rope-attachment-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown_-_Rope_Attachment/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"triceps-pushdown-rope-attachment-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown_-_Rope_Attachment/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Trizeps.","instructions":null}},{"id":"ex-upright-cable-row","slug":"upright-cable-row","name":"Upright Cable Row","description":"Cable exercise for the back, with shoulders assisting.","instructions":["Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The bar should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the cable bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["SHOULDERS"],"equipment":"CABLE","tags":["upright cable row"],"media":[{"id":"upright-cable-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Cable_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"upright-cable-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Cable_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken, unterstützt von Schultern.","instructions":null}},{"id":"ex-wide-grip-lat-pulldown","slug":"wide-grip-lat-pulldown","name":"Wide-Grip Lat Pulldown","description":"Cable exercise for the back, with biceps, shoulders assisting.","instructions":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.","After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"CABLE","tags":["wide-grip lat pulldown"],"media":[{"id":"wide-grip-lat-pulldown-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"wide-grip-lat-pulldown-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-worlds-greatest-stretch","slug":"worlds-greatest-stretch","name":"World's Greatest Stretch","description":"Equipment-free exercise for the hamstrings, with calves, glutes, quadriceps assisting.","instructions":["This is a three-part stretch. Begin by lunging forward, with your front foot flat on the ground and on the toes of your back foot. With your knees bent, squat down until your knee is almost touching the ground. Keep your torso erect, and hold this position for 10-20 seconds.","Now, place the arm on the same side as your front leg on the ground, with the elbow next to the foot. Your other hand should be placed on the ground, parallel to your lead leg, to help support you during this portion of the stretch.","After 10-20 seconds, place your hands on either side of your front foot. Raise the toes of the front foot off of the ground, and straighten your leg. You may need to reposition your rear leg to do so. Hold for 10-20 seconds, and then repeat the entire sequence for the other side."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES","QUADRICEPS"],"equipment":"NONE","tags":["world's greatest stretch"],"media":[{"id":"worlds-greatest-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Worlds_Greatest_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"worlds-greatest-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Worlds_Greatest_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelrückseite, unterstützt von Waden, Po, Oberschenkelvorderseite.","instructions":null}}];
